window.SAQ_PAPER_QUESTIONS["2020-1-islhd"]=[{"number":1,"title":"","stemText":"You are working for a prehospital and retrieval medicine service and fly 150km in a rotary wing\naircraft to attend an 18 year old man who has been involved in a motor vehicle accident\nOn your arrival his observations are:\n\nT 36.3\nP110\n\nBP 158/63\n\nRR 22\n\nSaO2 98%\nNo stridor but a mild degree of respiratory distress","parts":[{"id":"a","label":"Part A","prompt":"Referring to the above clinical photograph and Xray, describe the main findings (2 marks) as well as the main potential acute complications (2 marks) You decide to transport the patient without securing the airway as the tertiary receiving hospital has access to definitive surgical care as well as advanced airway equipment. The retrieval coordinator asks you whether you would like to transport the patient back via road or air. Outline 1 pro and 1 con to each mode of transport relevant to this case. (4 marks) Pro Con Rotary wing Road Transfer You elect to transfer the patient back by air and inflight the patient develops increasing respiratory distress then has a respiratory arrest. The pilot states you are unable to land for 18 minutes. You are unable to establish effective bag-valve mask ventilation despite adjuncts. Explain two management\n• ptions you would institute whilst in flight (4 marks)"}],"propPages":["asset:img4d5263068959d0d776","asset:img09b0ad11ebd760dc01"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Metallic FB, entering submandibular </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Penetrating floor of mouth but not hard palate </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Left hand side, displacing tongue to right </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">No obvious bony or airway injury </span></div><div class=\"answer-line\">You decide to transport the patient without securing the airway as the tertiary receiving hospital has</div><div class=\"answer-line\">access to definitive surgical care as well as advanced airway equipment. The retrieval coordinator</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 27 year old man with 3 days of abdominal pain, vomiting and diarrhoea has been admitted to the Emergency Department Short Stay Unit for intravenous fluid therapy and supportive care. He is still feeling unwell the next morning and isn’t suitable for discharge. He has bloods taken which are below. 7.35-7.45\n\npH\n7.19\n\npCO2\n35-45mmHg 80-100mmHg\n\npO2\n22-26mmol/L\n\nHCO3\n135-145mmol/L\n\nNa\n143 3.5-5mmol/L\n\nK\n2.8 96-106mmol/L\n\nCl\n114\n\nLactate\n1.8 < 2 mmol/L","parts":[{"id":"a","label":"Part A","prompt":"Please interpret the above venous blood gas (4 marks)"},{"id":"b","label":"Part B","prompt":"Name the two most likely contributors to this acid-base disturbance (1 mark)"},{"id":"c","label":"Part C","prompt":"Name 3 other causes of the predominant disturbance (3 marks)"},{"id":"d","label":"Part D","prompt":"Outline two important aspects of correcting this disturbance (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">pH = 7.19 = low = acidaemia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">pO2 = 42 = low = venous sample, unreliable (no mark allocated) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">HCO3 = 15 = low = metabolic acidosis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">CO2 = 30 = low = compensatory (expected CO2 = 8 + 1.5 x 15 = ~31) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Anion Gap = 143-(15+114) = 143 – 129 = 14 = high </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Na normal (no mark allocated) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">K = 2.8 = low (expected given pH, K ~6, thus critically low) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Delta ratio = (14-12) / (24-15) = 2/9 = isolated NAGMA </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Summary: Isolated NAGMA with critical hypokalaemia</span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Hyperchloraemia (likely secondary to saline administration) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Diarrhoea causing HCO3 loss</span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Adrenal insufficiency </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Renal tubular acidosis (Type 1,2,4) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Renal insufficiency (mild-moderate) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Drugs: Acetazolamide, Spironolactone </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">GI fistulas etc </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Correction/Replacement of K+ (likely also MgSO4) is main priority prior to correcting HCO3 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Isotonic bicarbonate solution: 150mmol NaHCO3 in 850mL 5% Dextrose to replace HCO3 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"You are working as the consultant in a tertiary hospital and your intern has just seen a 23 year old woman who is 6 days following a vaginal delivery, assisted with obstetric forceps. She was discharged day 2 with a healthy girl and has returned to the emergency department with fevers.\nHer vital signs are:\n\nT 39.2\nP 133\n\nBP 85/50\n\nRR 24\n\nSaO2 99% RA","parts":[{"id":"a","label":"Part A","prompt":"You suspect endometritis, name 2 organisms from different categories (2 marks)"},{"id":"b","label":"Part B","prompt":"Name 3 other causes of post-partum fever to consider in this case (3 marks)\nA transvaginal ultrasound is performed (below) and shows a distended endometrial cavity with heterogenous material without internal vascularity."},{"id":"c","label":"Part C","prompt":"Outline the specific treatment you would facilitate for this woman (3 marks)"}],"propPages":["asset:imgbb7746302e9ccd93f7"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Gram Positive: Staphylococcus / Streptococcus </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Gram Negative: E. Coli / Proteus / Enterobacter </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Anaerobic: Bacteroides / Peptostreptococus / Clostridium </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Perineal tear / episiotomy infection +/- collection </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Mastitis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Urinary Tract Infection </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Intravenous broad spectrum antibiotics: Ceftriaxone 1g IV, Metronidazole 500mg IV </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Penicillin = 0/3 for sub-section </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Intravenous fluid resuscitation / Hartmanns / Aim to maintain MAP &gt;65 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Source control: Suction evacuation (some controversy within 24hrs, doesn’t need to be addressed) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">No marks for disposition </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"You are working on shift in a rural emergency department with a single junior medical officer. The nearest major referral hospital is 400km away. You receive a 20 year old man who has been shot in the mid-thigh, with a shotgun and has brisk haemorrhage from the entry site.\nHis vital signs on arrival are:\n\nT 36.2\nP 172\n\nBP 58/27\n\nGCS 8 (E2V2M4)\n\nRR 24\n\nSaO2 no trace recordable","parts":[{"id":"a","label":"Part A","prompt":"Outline your immediate management (3 marks) The patient clinically improves, but due to weather and other factors the retrieval coordination service advises you the patient won’t be able to reach the referral hospital for ~4 hours."},{"id":"b","label":"Part B","prompt":"Name 3 complications associated with tourniquet use (3 marks)"},{"id":"c","label":"Part C","prompt":"Explain the concept ‘tourniquet conversion’ (2 marks)"},{"id":"d","label":"Part D","prompt":"List 2 possible indications for tourniquet conversion (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Apply tourniquet (e.g. combat application tourniquet) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Immediate blood transfusion O Neg (these hospitals usually have 2-4 units) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Titrate to cerebral perfusion / Systolic BP ~80 initially </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">TXA 1g </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Limb loss (incidence likely &lt;1%) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Compartment syndrome (2-4%) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Myonecrosis, Rhabdomyolysis, Acute kidney injury (2-4%) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Nerve injury (2-4%) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Venous thromboembolism (2-4%) </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Tourniquet conversion is an important concept which refers to the aim of removing a </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">tourniquet and replacing it with a haemostatic agent and/or pressure dressing. The goal of </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">this is to reduce the potential for significant complications but again the ‘life over limb </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">principle’ applies and this should only be done if clinically appropriate. </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Bleeding controlled </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Haemostatic agent / pressure dressing effective </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Prolonged transport – e.g. &gt;2hrs (not low risk) </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"You are working in an urban district emergency department and have just received a 73 year old man with a long history of smoking, hypertension and COPD who has presented with extreme dyspnoea and hypoxia.\nHis vital signs are:\n\nT 36.3\nP 122\n\nBP 177/98\n\nRR 42\n\nSaO2 82% on 10L/min via Hudson mask\nYou perform point of care ultrasound (PoCUS) and obtain the following pattern globally throughout the lungs in association with bilateral lung sliding.","parts":[{"id":"a","label":"Part A","prompt":"What is the likely diagnosis? (1 mark)"},{"id":"b","label":"Part B","prompt":"What is the main feature on this image suggestive of this diagnosis (1 mark)"},{"id":"c","label":"Part C","prompt":"Outline the two main aspects of your initial care of this man (4 marks)"},{"id":"d","label":"Part D","prompt":"Please provide 2 findings on PoCUS for the following lung conditions (6 marks)\nPneumonia\n• \nCOPD\n• \nPneumothorax\n•"}],"propPages":["asset:img6577a62eb5789bd4f3"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Acute Pulmonary Oedema </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Widespread B lines </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">GTN Infusion / High dose initially (400mcg/min or sublingual loading) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">NIV: CPAP or BiPAP reasonable if appropriate detailed settings given  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">CPAP 5-10cmH20 initially, fiO2 100% initially with target SaO2 88-92% given COPD Hx </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">BiPAP 10-15/5-10cmH20 initially, fiO2 100% as above, titrate up EPAP/PEEP </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Pneumonia</div><div class=\"answer-line\"><span class=\"answer-source-red\">Irregular pleural line </span></div><div class=\"answer-line\">ISLHD Emergency Medicine Trial Written Fellowship Exam 2020.1</div><div class=\"answer-line\"><span class=\"answer-source-red\">Localised B line profile </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Hepatinisation of lung tissue </span></div><div class=\"answer-line\">•</div><div class=\"answer-line\">COPD</div><div class=\"answer-line\"><span class=\"answer-source-red\">A line profile </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Lung sliding </span></div><div class=\"answer-line\">•</div><div class=\"answer-line\">Pneumothorax</div><div class=\"answer-line\"><span class=\"answer-source-red\">Absent lung sliding </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Lung point 100% specific </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 58 year old man has been referred from his GP with a painful skin rash that initially started as oral mucosa lesions several weeks prior. He has a background of hypertension and smoking but is\n• therwise slim and doesn’t have any other comorbidities. He is in significant discomfort but his vital\nsigns are normal. A clinical photograph is below","parts":[{"id":"a","label":"Part A","prompt":"Describe the photograph above (3 marks)"},{"id":"b","label":"Part B","prompt":"What is the most likely diagnosis? (1 mark) Name 2 differential diagnoses and a clinical feature that may distinguish them from your provisional diagnosis (4 marks)"},{"id":"c","label":"Part C","prompt":"How is the diagnosis confirmed? (1 mark)"},{"id":"d","label":"Part D","prompt":"Outline the management priorities for this condition (3 marks)"}],"propPages":["asset:img2363bba16600e7b6eb"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Widespread erythematous lesions </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Thin-walled blisters, mostly ruptured </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Involving shoulders and most of central back </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Pemphigus vulgaris </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Biopsy </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Immunofluorescence - IgG or compliment on surfaces of keratinocytes </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">ISLHD Emergency Medicine Trial Written Fellowship Exam 2020.1</div><div class=\"answer-line\"><span class=\"answer-source-red\">Specific Mx: Corticosteroids are mainstay (reduce mortality 99% -&gt; 5-15%) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Supportive Mx:  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Analgesia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Wound care </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Seek and treat underlying infection </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 21 year old man is brought into the ED with palpitations that came on 2 hours prior and were unprovoked. His ECG is shown below. He has been recently diagnosed with Wolf-Parkinson-White syndrome but has had no treatment to date.\nHis vital signs are:\n\nT 36.7\n\nBP 132/87\n\nRR 22\n\nSaO2 99% RA\n\nGCS 15","parts":[{"id":"a","label":"Part A","prompt":"What is the diagnosis? (1 mark)"},{"id":"b","label":"Part B","prompt":"What ECG features suggest this diagnosis? (3 marks)"},{"id":"c","label":"Part C","prompt":"How does this man’s history of WPW alter his emergency treatment? (1 mark)"},{"id":"d","label":"Part D","prompt":"Outline two management options for this man (2 marks)"}],"propPages":["asset:img15efc05c4c137aaa02"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">SVT with orthodromic conduction (both required for full mark) </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Regular rhythm </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">No P Waves </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Narrow complex suggests orthodromic conduction (as opposed to antidromic) </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">It doesn’t in this case </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">In WPW atrial fibrillation, AV nodal blockers are contraindicated  </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Vagal manoeuvres – e.g. augmented Valsalva </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">AV nodal blocker: Adenosine / Verapamil with correct dose </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">DC cardioversion NOT appropriate as initial Mx (suspect some may use this) </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"You receive a pre-hospital notification that your department will be receiving an 18 year old man who has been struck repeatedly with an aluminium baseball bat across the face. He has an altered level of consciousness is bleeding profusely from the nose and mouth and has an obviously deformed / depressed face.","parts":[{"id":"a","label":"Part A","prompt":"List your main priorities for the initial treatment of this man (3 marks)"},{"id":"b","label":"Part B","prompt":"How does midface trauma complicate laryngoscopy? (1 mark) Describe how you would plan to modify a standard rapid sequence induction for this patient (4 marks) Following successful intubation, outline your technique for minimising ongoing haemorrhage from the midface (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Secure airway </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Haemorrhage control </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Volume resuscitation as required </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Haemorrhage obscuring view / rendering  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">The actual geometry of the airway is rarely altered/worsened (no mark for this) </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 12 year old girl is bought in to emergency by her mother, who appears intoxicated and leaves the department without notice soon after and is unable to be contacted. The girl has abdominal pain and you suspect acute appendicitis. Current observations are\n\nGCS 15\n\nBP 105/77\n\nHR 95\n\nSat 100% RA\nT37.8","parts":[{"id":"a","label":"Part A","prompt":"List 4 ultrasound findings that increase the suspicion of appendicitis (4 marks)\nList two factors on history that would make you suspect a perforated appendix in this patient (2 marks) She is reviewed by the surgical registrar who decides she is best managed operatively. List 5 reasons"},{"id":"b","label":"Part B","prompt":"why a patient may be unable to give informed consent? (5 marks) You assess the girl as competent and mature. She refuses surgery on the grounds her grandmother"},{"id":"c","label":"Part C","prompt":"died in your hospital. Explain the concept of a mature minor in this case (3 marks)\nBook 2"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Appendiceal diameter &gt; 6 mm </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Target sign with 5 concentric layers </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Distension or obstruction of the appendiceal lumen </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">High echogenicity surrounding the appendix </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Appendicolith </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Periceacal or perivesical free fluid </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Muscular wall thickness &gt; 2 mm </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Absence of appendiceal peristalsis </span></div><div class=\"answer-line\">List two factors on history that would make you suspect a perforated appendix in this patient (2</div><div class=\"answer-line\">marks)</div><div class=\"answer-line\"><span class=\"answer-source-red\">Pain &gt; 36 hours duration </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Pain free interval </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Diffuse pain (less likely isolated to RIF) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Vomiting  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Fever/s </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Alteration of bowel habit </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Not accepted – sepsis, systemically unwell, HD unstable etc as this is given to you in the stem </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><span class=\"answer-source-red\">Not voluntary (coerced) </span></td></tr><tr><td><span class=\"answer-source-red\">-</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Lack capacity </span></td></tr><tr><td><span class=\"answer-source-red\">-</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Are a minor </span></td></tr><tr><td><span class=\"answer-source-red\">-</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Not informed properly (eg consent obtained by someone not familiar with procedure/risks not </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">explained) </span></td></tr><tr><td><span class=\"answer-source-red\">-</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Under the mental health act </span></td></tr><tr><td><span class=\"answer-source-red\">-</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Cannot comprehend information presented to them </span></td></tr><tr><td><span class=\"answer-source-red\">-</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Others accepted as long as sensible and no overlap with other answers </span></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><span class=\"answer-source-red\">3 factors for 3 marks </span></td></tr><tr><td><span class=\"answer-source-red\">-</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">&lt;18 (no lower age limit) </span></td></tr><tr><td><span class=\"answer-source-red\">-</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Reasonable thought process and insight (any description long these lines) </span></td></tr><tr><td><span class=\"answer-source-red\">-</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Can consent to treatment but cannot withhold consent or refuse life-saving treatment </span></td></tr><tr><td colspan=\"2\">ISLHD Emergency Medicine Trial Written Fellowship Exam 2020.1</td></tr><tr><td colspan=\"2\">Book 2</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"You are the trauma team leader in a tertiary emergency department and you are receiving an unstable blunt trauma patient who has been struck by a truck whilst riding a motor cycle. The prehospital team has performed an RSI, bilateral finger thoracostomies, placed a pelvic binder and commenced a blood transfusion with 4 units of O negative blood. The patient dies in the emergency department. During review of the case, it is suggested that the patient may have benefited from resuscitative endovascular balloon occlusion of the aorta (REBOA).","parts":[{"id":"a","label":"Part A","prompt":"What is the main indication for REBOA? (1 mark)"},{"id":"b","label":"Part B","prompt":"Complete the following table regarding REBOA catheter placement (4 marks)"},{"id":"c","label":"Part C","prompt":"Name one alternative to REBOA in this setting (1 mark)"},{"id":"d","label":"Part D","prompt":"Describe the surface anatomy of the common femoral artery (2 marks) You are asked by your director to gather information towards developing a business case to institute"},{"id":"e","label":"Part E","prompt":"REBOA into your department. State 5 aspects to your research (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Exsanguinating subdiaphragmatic haemorrhage </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Exsanguinating subdiaphragmatic haemorrhage </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Thoracotomy and aortic occlusion (manually is preferable, or cross clamp) </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Mid inguinal point </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Artery is lateral to vein </span></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Current literature on REBOA </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Availability of equipment in the hospital, area health service or nationally </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Benchmarking (use in other centres of similar size, epidemiology) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Cost analysis (lifetime + consumables) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Risk Management (potential problems / risk mitigation strategies) </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 12 month old girl is brought in by her parents after they found her playing with an open bottle of her mothers antiepileptic medication. This occurred around an hour before arrival in the ED and upon counting remaining tablets it is suspected she may have taken 5 tablets","parts":[{"id":"a","label":"Part A","prompt":"Discuss the main features of toxicity in this ingestion (4 marks)"},{"id":"b","label":"Part B","prompt":"What is the expected weight for this child? (1 mark)"},{"id":"c","label":"Part C","prompt":"Outline your dose-related risk assessment for this child (1 mark) The child develops significant toxicity and is intubated. Both multiple dose activated charcoal (MDAC) and haemodialysis can be used as enhanced elimination techniques."},{"id":"d","label":"Part D","prompt":"Describe how you would perform MDAC in this child (3 marks)"},{"id":"e","label":"Part E","prompt":"Name 2 other agents in which MDAC may be used (2 marks)"},{"id":"f","label":"Part F","prompt":"List 2 indications for extracorporal elimination in this child (2 marks)"},{"id":"g","label":"Part G","prompt":"List 3 properties of drugs that make them ideal for haemodialysis (3 marks)"}],"propPages":["asset:img225e6e33353e03f1cd"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Anticholinergic toxicity </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">ALOC -&gt; Coma </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Cardiotoxicity:  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Na+ channel blockade and arrythmias </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Hypotension </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">10kg </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">5x 200mg = 1000mg </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">~100mg/kg </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">?50mg/kg can cause significant life-threatening toxicity </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">NG/OG tube (confirm placement) ~8Fr </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">1g/kg activated charcoal </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">0.5g/kg q2hrs / reassess need at ~6hrs </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Check bowel sounds and aspirate NG/OGT prior to each dose </span></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Theophylline </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Quinine </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Dapsone </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Phenobarbitone </span></div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Prolonged coma with serum levels &gt;40mg/L (120micromol/L) after 48 hours </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Haemodynamic instability </span></div></section><section class=\"answer-part\"><h5>Part G</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Small molecule </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Small volume of distribution </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Rapid redistribution from tissues </span></div><div class=\"answer-line\">ISLHD Emergency Medicine Trial Written Fellowship Exam 2020.1</div><div class=\"answer-line\"><span class=\"answer-source-red\">Slow endogenous elimination </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 34 year old man is brought to your emergency department following a work place injury. He was using a pressurised paint injector with a high-pressure hose that snapped, striking him in his hand. He washed his hand immediately and presented to the department. He is complaining of pain and has been given oral analgesics with some relief to his pain. His vital signs are normal. A picture of his hand post injury is attached.","parts":[{"id":"a","label":"Part A","prompt":"What is your choice of initial investigation and your rationale for it? (2marks )"},{"id":"b","label":"Part B","prompt":"What are your immediate management priorities? List 5. (5 marks ) You have difficulty managing this man’s pain and your resident suggests a peripheral nerve block."},{"id":"c","label":"Part C","prompt":"What is your response and what are the additional options (3 marks)"}],"propPages":["asset:img69dd5ede237544deb0"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Hand X-ray. </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">May show extent of injection of radiopaque substanes. </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Splint and Elevate </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Emergent ortho/hand surgeon consult </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Early surgical decompression and debridement </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Increased rate of amputation if &gt;10 hours to OR </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Tetanus </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Antibiotics </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Analgesia </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Digital blocks are contraindicated as wound already under high pressure. May mask developing </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">compartment syndrome.</span></div><div class=\"answer-line\"><span class=\"answer-source-red\">IV Morphine 5-10mg q30 mins </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Low dose ketamine 10-20mg / or infusion </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">IV Fentanyl PCA – titrated to pain. </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 58yo man presents to the emergency department with nausea, vomiting, pruritis, back pain and reduced urine output over the last 2 days. He is currently being investigated for a retroperitoneal mass. His VBG shows a creatinine of 634.","parts":[{"id":"a","label":"Part A","prompt":"What are the main causes of AKI? Include 2 examples of each (3 marks)"},{"id":"b","label":"Part B","prompt":"Outline 3 investigations you would perform in the ED for this patient. Justify each (3 marks)"},{"id":"c","label":"Part C","prompt":"List 5 indications for Continuous Renal Replacement Therapy (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Prerenal: hypovolaemia, renal artery stenosis, heart failure, sepsis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Renal: renal vein thrombosis, vasculitis, drugs (NSAIDs, ACEI, ARBs)  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Post renal: retroperitoneal neoplasm, renal calculus, urinary retention </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Any 2 correct from each group </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">CT Abdo (abdominal mass, hydronephrosis) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Better than US as known mass </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">VBG (metabolic acidosis, hyperkalaemia)  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">ECG (hyperkalaemia)  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Urinalysis (infection / haematuria / proteinuria) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Others may be reasonable </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">K&gt;6.5 or rapidly rising  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Na &lt;100 or &gt;160  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Pulmonary oedema unresponsive to diuretics  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Severe uncompensated metabolic acidosis with pH&lt;7.1 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Uraemic Syndrome  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Overdose with dialysable toxin  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Urea &gt;35 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Creatinine &gt;400 </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"You are accompanying a Climbing team to the Everest Base camp on the Tibetan side of the\nmountain. The altitude is 5150m. A 30 year old man who has suffered Nausea, vomiting and\nheadache over the past week has been breathless at rest over last couple of days and is only talking in short sentences. His vital signs are:\n\nT: 37.2\n\nHR: 110\nO2sat 84%\n\nRR 28\n\nBP: 134/78","parts":[{"id":"a","label":"Part A","prompt":"What is the most likely diagnosis? Outline 3 management interventions (4 marks) What was the most likely explanation for his preceding symptoms? What would the most"},{"id":"b","label":"Part B","prompt":"appropriate management have been? (3 marks) High altitude cerebral oedema can also occur in this situation. Name 2 clinical features and 1 specific medication for this condition. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">High altitude pulmonary oedema </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Oxygen </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Nifedipine 30 mg BD po </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Descend </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Acute mountain sickness </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Acetazolamide 250 mg PO BD </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 32 year old man presents to the emergency department with painful defecation and a tender swelling adjacent to his anus. You diagnose a superficial perianal abscess.","parts":[{"id":"a","label":"Part A","prompt":"List the 3 other anatomical types of perianal abscess (3 marks)\nYou elect to perform an incision and drainage on his superficial perianal abscess. He is adequately"},{"id":"b","label":"Part B","prompt":"sedated by a senior colleague in your resuscitation room. Outline your approach (4 marks) You successfully drain his perianal abscess. List 3 aspects of your post-procedure care of this man (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Ischiorectal fossa abscess </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Intersphincteric abscess </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Supralevator abscess </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Position in lithotomy (may need an assistant) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Prep and drape area </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Radial incision into cavity – take swab </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Blunt dissect cavity with forceps / finger </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Irrigate with normal saline </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 26 year old woman who is breastfeeding her 3 week old girl has developed fevers, rigors and left breast pain. She is haemodynamically stable and you suspect mastitis.","parts":[{"id":"a","label":"Part A","prompt":"List 2 risk factors for mastitis (2 marks)"},{"id":"b","label":"Part B","prompt":"Name 2 organisms that commonly cause mastitis? (2 marks)\nYou decide to admit the woman and place her on intravenous antibiotics. Please outline two antimicrobial regimens (include dose, route and frequency) First Line (1 mark) Beta-lactam allergy (1 mark)"},{"id":"c","label":"Part C","prompt":"Describe the image and state the most likely diagnosis (2 marks)"},{"id":"d","label":"Part D","prompt":"Outline the preferred management of the above condition (2 marks)"},{"id":"e","label":"Part E","prompt":"Outline 2 important aspects of breast-feeding advice for this patient (2 marks)"}],"propPages":["asset:img5421018305dc2ce8d0"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Staphylococcus aureus (essential) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">o</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">MRSA becoming increasingly common </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Beta-haemolytic streptococcus e.g. group A strep </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">E Coli </span></div><div class=\"answer-line\">You decide to admit the woman and place her on intravenous antibiotics. Please outline two</div><div class=\"answer-line\">antimicrobial regimens (include dose, route and frequency)</div><div class=\"answer-line\">First Line (1 mark)</div><div class=\"answer-line\"><span class=\"answer-source-red\">Flucloxacillin 2g IV q6H </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Cephazolin 2g IV TDS </span></div><div class=\"answer-line\">Beta-lactam allergy (1 mark)</div><div class=\"answer-line\"><span class=\"answer-source-red\">Lincomycin 600mg IV q8H </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Clindamycin 450mg IV q8H </span></div><div class=\"answer-line\">ISLHD Emergency Medicine Trial Written Fellowship Exam 2020.1</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Hypoechoic, round region beneath the skin </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Breast abscess </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Needle aspiration </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">I&amp;D not done as first line </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Up to 3x daily needle aspirations / usually US-guided </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Hypoechoic, round region beneath the skin </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Breast abscess </span></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><span class=\"answer-source-red\">o</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">May need to re-position baby if aspirations done or drain in-situ </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">See midwife / lactation consultant to determine underlying trigger and prevent </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">future </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 32 year old woman comes to the ED with persistent vomiting and epigastric discomfort. She has no\n• ther symptoms. She has no significant comorbidities with the exception of significant weight loss\nfollowing laparoscopic gastric banding done 3 years ago.","parts":[{"id":"a","label":"Part A","prompt":"What is the most significant finding on this AXR? What is the normal appearance? (2 marks)"},{"id":"b","label":"Part B","prompt":"What is the diagnosis? (1 mark)"},{"id":"c","label":"Part C","prompt":"How common is this? (1 mark)"},{"id":"d","label":"Part D","prompt":"List 2 complications of this condition (2 marks)"},{"id":"e","label":"Part E","prompt":"Outline your management (4 marks)"}],"propPages":["asset:imgcf82661d4a41bd834b","asset:img23d5c6ef1abe39f8da"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Phi angle significantly greater than normal (usually 4-58o). Suggest band slippage. </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"> The Phi (φ) angle of the band is the angle formed by a straight line through the long axis of the band </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">and a vertical line through the spinal column </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Band slippage </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">12%, usually occurs after 3 months </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">This is a fairly typical presentation </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Intolerance of food/fluid – dehydration and its consequences </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Gastric necrosis / perforation </span></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Analgesia / Antiemetics (not prokinetic) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">NBM / IV Fluids (deficit + maintenance) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Aspirate balloon to deflate (usually ~5mL) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Refer to surgical team to facilitate further inpatient Ix and Mx </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">o</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">May get contrast study or CT with PO contrast to assess for perforation </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">o</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Often get endoscopy and/or laparoscopy to identify further damage </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"You are working as a new consultant in a rural emergency department and have been tasked with developing a clinical governance team to augment the local health care service","parts":[{"id":"a","label":"Part A","prompt":"What is clinical governance? (3 marks)"},{"id":"b","label":"Part B","prompt":"List the 7 pillars of clinical governance (7 marks)"},{"id":"c","label":"Part C","prompt":"What is the main difference between research and audit? (2 marks)\nBook 3"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">System by which the governing body, managers, clinicians and staff  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">share responsibility and accountability  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">for the quality of care, continuously improving, minimising risks, and fostering an </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">environment of excellence in care for patients and consumers.   </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><span class=\"answer-source-red\">Patient &amp; Public Involvement </span></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Information &amp; IT </span></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Risk Management </span></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Audit </span></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Training / Education </span></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Clinical Effectiveness and Research </span></td></tr><tr><td><span class=\"answer-source-red\">•</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Staff management </span></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Research = what is the right thing to do? </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Audit = are we doing the right thing? </span></div><div class=\"answer-line\">ISLHD Emergency Medicine Trial Written Fellowship Exam 2020.1</div><div class=\"answer-line\">Book 3</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"You are an ED physician working in a mixed tertiary ED when a 2 year old boy is brought in by his step-father refusing to weight bear, agitated and distressed. His stepfather states that he been limping for a few days, but becomes defensive on specific questioning. He is 12kg and has normal vital signs. You are concerned for the possibility of non-accidental injury. In addition to non-accidental injury, what are three other differentials for a limb in this patient? (3 marks) On examination, you notice several bruises around the trunk and circumferentially around the upper arm of the child. The stepfather states “he falls a lot”.","parts":[{"id":"a","label":"Part A","prompt":"Name 5 other examination findings that may be consistent with non-accidental injury (5 marks) Given your concerns, you decide to perform a skeletal survey and find several old fractures, healing at different stages across several limbs. Name two other differentials apart from non-accidental"},{"id":"b","label":"Part B","prompt":"injury that may give a similar appearance on imaging. (2 marks) The child remains irritable and inconsolable in the ED. What other investigation would you consider?"},{"id":"c","label":"Part C","prompt":"Provide justification. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Bite marks </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Burns (especially cigarettes) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Broken frenulum </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Retinal haemorrhages on fundoscopy </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Bruising around mastoid area </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Perineal or genital trauma/mutilation </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Obvious neglect ie very poor hygiene </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Abnormal behaviours demonstrated between child/parent </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Osteogenesis imperfecta </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Osteopetrosis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Severe malnutrition </span>→<span class=\"answer-source-red\"> osteopenia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Chronic kidney or liver disease </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">CT head </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Child remaining irritable – may be marker of concealed injury </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Exclude intracranial bleeding from shaken child injury </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Exclude skull fracture from blunt trauma </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A concerned parent of a 15 month old boy presents to your emergency department with concerns for measles after her child has developed fever at home of 39.5 degrees. She was notified some days prior of exposure to a confirmed case of measles during a flight from overseas. The child does not have a visible rash.","parts":[{"id":"a","label":"Part A","prompt":"What is the incubation period for measles (1 mark)\nList 3 signs on examination that would lead you to suspect measles over other\ncauses of fever (3 marks) You are suspicious this may be measles."},{"id":"b","label":"Part B","prompt":"List 3 specific investigations you would perform (3 marks)"},{"id":"c","label":"Part C","prompt":"Describe the appearance of the measles rash (2 marks)"},{"id":"d","label":"Part D","prompt":"List 3 complications from the measles virus in this patient (3 marks)\nThe child examines otherwise well and a decision is made for discharge after"},{"id":"e","label":"Part E","prompt":"appropriate investigations. Outline your discharge advice for the mother. (3 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Accept between 6 and 21 days, median is 13 </span></div><div class=\"answer-line\">List 3 signs on examination that would lead you to suspect measles over other</div><div class=\"answer-line\">causes of fever (3 marks)</div><div class=\"answer-line\"><span class=\"answer-source-red\">Koplik Spots </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Non purulent conjunctivitis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Pharyngitis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Lymphadenopathy </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Splenomegaly </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Nose/Throat swab for PCR </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Urine PCR </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Blood serology (IgM and IgG) </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Marks for </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Cranio caudal progression (starts on face) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Palms and soles rarely involved </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Maculopapular, Mobilliform, Erythematous (must have 2/3 for 1 mark) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">No marks for blanching as can be petechial especially later </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Encephalitis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Pneumonia (also accept bronchiolitis) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Otitis media </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Immune suppression </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Bacterial superifection </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Subsclerosing pan encephalitis </span></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Contagious – highest risk 5 days before and 4 days after rash. Should stay at home </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">until at least 4 days after rash. Must mention contagious, 1 mark for mention </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">another mark for timeframe.  </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Other advice maximum 1 mark for sensible answers eg </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Follow up plan for results </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Warning about complications </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Expected clinical course </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Contact tracing </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 7 week old boy is brought in by his parents with inconsolable crying for 16 hours. The parents look exhausted and dejected. The boy has unremarkable birth history and is thriving.","parts":[{"id":"a","label":"Part A","prompt":"List the potential causes of the boys crying (5 marks)"},{"id":"b","label":"Part B","prompt":"What are important features in history that need to be obtained? (5marks) You do not find a significant cause for the boys crying and decide to discharge him. What approach"},{"id":"c","label":"Part C","prompt":"to discharge would you use? (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>T</strong></span><span class=\"answer-source-red\"> — Trauma (accidental and nonaccidental injuries) and bites (e.g. insects), tumours </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>I</strong></span><span class=\"answer-source-red\"> — Infections (otitis media, herpes stomatitis, urinary tract infection, meningitis, </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">osteomyelitis, etc) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>M</strong></span><span class=\"answer-source-red\"> — Maternal/ parental stress, anxiety or depression </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>S</strong></span><span class=\"answer-source-red\"> — Strangulation (hair/fiber tourniquet) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>C</strong></span><span class=\"answer-source-red\"> — Cardiorespiratory disease </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>R</strong></span><span class=\"answer-source-red\"> — Reflux, reactions to medications, reactions to formulas, rectal (anal fissures) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>I</strong></span><span class=\"answer-source-red\"> — Intracranial hypertension, immunizations, intolerance of lactose or cow’s milk allergy </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>E</strong></span><span class=\"answer-source-red\"> — Eye (corneal abrasions, ocular foreign bodies, glaucoma, retinal haemorrhages) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\"><strong>S</strong></span><span class=\"answer-source-red\"> — Surgical (volvulus, intussusception, inguinal hernia, testicular torsion) </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Temporal association of crying with feeds. </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Variation of crying with contextual or environmental factors. </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Parental response — in terms of emotional responses and actions. </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">The parents support system. Screen for depression. Consider the potential for non-</span></div><div class=\"answer-line\"><span class=\"answer-source-red\">accidental injury. </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Growth and development — physical causes of chronic crying are rare if the child is thriving. </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Associated symptoms — e.g. vomiting, diarrhoea, eczema. </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Explain that the infant is not unwell or in pain and that crying and unsettled behaviour will </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">improve with time. </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Provide empathic acknowledgment of anxiety and stress, constructive options for ongoing </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">support from within and outside the family. </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Provide printed information with management advice and support contacts </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Follow up with Maternal/ child health nurse, General practitioner or General paediatrics </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">have been arranged </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Offer Inpatient admission — for severe cases or if there is risk of parental exhaustion or non-</span></div><div class=\"answer-line\"><span class=\"answer-source-red\">accidental injury to the infant. </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 17 year old female has been brought in from school after a collapse. Her mother tells you that her GP has referred her to a psychiatrist over concerns of her body weight, they suspect she has an eating disorder. They are currently awaiting an appointment.","parts":[{"id":"a","label":"Part A","prompt":"Define Anorexia Nervosa (2 marks)"},{"id":"b","label":"Part B","prompt":"Define Bulimia Nervosa (2 marks)"},{"id":"c","label":"Part C","prompt":"List 4 complications of Anorexia Nervosa from 4 separate systems (4 marks)"},{"id":"d","label":"Part D","prompt":"List 4 criteria for medical admission in anorexia Nervosa (4 marks)\nMaximum of 1 indication per body system"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Restriction of calorie intake resulting in pathologically low body weight </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Repetitive and Compulsive episodes of Binge eating </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Compensatory actions to stop from gaining weight (Purging / Laxatives / Diuretics) </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">CVS - Syncope / Dysrrhythmias </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Met - Hypoglycaemia / Hypo(K/Mg/PO4/Na) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Haem - Anaemia, Neutropaenia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">GI - Liver Failure, Constipation </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Skeletal - Osteoperosis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Psychiatric - Depression </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Refeeding Syndrome - Hypo K/Mg/PO4/glycaemia </span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">CVS - Syncope / Dysrrhythmias </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Met - Hypoglycaemia / Hypo(K/Mg/PO4/Na) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Haem - Anaemia, Neutropaenia </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">GI - Liver Failure, Constipation </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Skeletal - Osteoperosis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Psychiatric - Depression </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Refeeding Syndrome - Hypo K/Mg/PO4/glycaemia </span></div><div class=\"answer-line\">Maximum of 1 indication per body system</div><div class=\"answer-line\"><span class=\"answer-source-red\">BMI &lt; 12 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Hypothermia (&lt;35.5) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">CVS </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">- Brady cardia &lt; 50 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">- SBP &lt;80mmHg </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">- Postural Hypotension (&gt;20mmHg) </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Electrolytes </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">- K+ &lt; 3mmol/L </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">- Na &lt; 125mmol/L </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">- BSL &lt; 3mmol/L </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Haem - Neutrophils &lt; 0.7 </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Renal - eGFR&lt; 60mls/min </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Failure to respond to outpatient management </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 33 year old Indigenous man from remote Northern Territory presents during the wet season with 3 days of fever, cough and abdominal pain with decreased oral intake. He looks quite unwell from the end of the bed.\nHis vital signs are:\nP 120\n\nBP 85/50\n\nTemp 39.6\n\nSaO2 88% R/A\n\nGCS 14\nYour resident has ordered basic blood tests including VBG, FBC, EUC, CRP and blood cultures and ordered a CXR which is shown below.","parts":[{"id":"a","label":"Part A","prompt":"List 2 abnormal features on the CXR (2 marks)"},{"id":"b","label":"Part B","prompt":"List 3 potential causative organisms in this patient (3 marks)"},{"id":"c","label":"Part C","prompt":"List 2 further investigations with justification for each (4 marks)"},{"id":"d","label":"Part D","prompt":"Name 2 target areas of the federal ‘closing the gap’ framework (2 marks)"}],"propPages":["asset:imgd3ae3f3bea48ab3c6c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Right sided mediastinal amass </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Elevated right hemidiaphragm </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Cavitating lesions R UL (may be hard to appreciate, not required for 2/2) </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Mycobacterium tuberculosis </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Burkholderia pseudomallei </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Staphylococcus aureus  </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Investigation</th><th>Justification</th></tr></thead><tbody><tr><td><span class=\"answer-source-red\">CT brain, chest and abdomen with contrast </span></td><td>ISLHD Emergency Medicine Trial Written Fellowship Exam 2020.1</td></tr><tr><td><span class=\"answer-source-red\">Abscess formation common in melioidosis (patient septic with abdominal pain)– stem points </span></td><td><span class=\"answer-source-red\">to these areas </span></td></tr><tr><td><span class=\"answer-source-red\">Quantiferon gold, sputum AFB, sputum culture </span></td><td><span class=\"answer-source-red\">Diagnose/exclude TB </span></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Child mortality </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Indigenous 4 year olds enrolled in education </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">School attendance </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Reading and numeracy </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Year 12 attainment </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Employment </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Life expectancy </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"You are overseeing the care of a 63 year old woman with septic shock who has been given appropriate broad spectrum antibiotics and 2L of intravenous hartmanns solution. She has no clinically apparent source however her urine dipstick is positive for leukocytes and nitrites. She was previously healthy with no significant comorbidities, medications or known allergies. Her current vital signs are:\nP 122\n\nBP 72/40\n\nGCS 12 (E3V4M5)\n\nRR 32\n\nSaO2 poor trace\nYour registrar is planning to commence a noradrenaline infusion to support that patients MAP. They would like to insert a CVC prior to commencing therapy however you encourage them to start via peripheral IVC.","parts":[{"id":"a","label":"Part A","prompt":"What is the advantage of peripheral vasopressor therapy? What is the safety profile? (2 marks)"},{"id":"b","label":"Part B","prompt":"List 2 factors associated with reducing complications associated with extravasation (2 marks)"},{"id":"c","label":"Part C","prompt":"Outline your management of extravasation (4 marks) A central line is inserted in the right internal jugular vein and vasopressor therapy continued."},{"id":"d","label":"Part D","prompt":"List 3 modalities of confirming venous placement, including expected findings (3 marks)\nThe patient remains hypotensive despite 30mcg/min of noradrenaline. You are planning to commence a second vasoactive agent and perform a bedside cardiac ultrasound. Please suggest a second-line agent based on the following findings. Assuming no pericardial effusion, normal volume status, no RV strain (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Immediate therapy / avoids time delay (with organ hypoperfusion) associated with placing CVC </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Evidence suggests incidence of extravasation is low (&lt;2%), and ischaemic complications extremely </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">uncommon </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Risk vs. Benefit is almost always towards short term peripheral vasopressors to stabilise patient </span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Well placed IVC, if US-guided &gt;10mm in vessel </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Regular assessment of IVC site </span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Stop infusion </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Commence infusion via alternate IV access </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Aspirate IVC of all remaining vasopressor </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Administer vasodilator </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Subcutaneous infiltration of up to phentolamine (0.5mg/mL) via 25g needle </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Can consider administering phentolamine via the involved IVC, then remove </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Close monitoring of limb</span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">CXR – in SVC with tip just above RA </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">PoCUS –Saline flush test / visualise Wire moving freely within IJ on PoCUS </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Blood gas – reduced pO2 / O2 saturation </span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 10 year old boy with known haemophilia A presents to the emergency department with a painful ankle after trivial trauma at home. He has a diffuse tenderness and is unable to weight bear. He is systemically well. His X Ray shows no fracture. He weighs 30kg and his vital signs are normal.","parts":[{"id":"a","label":"Part A","prompt":"What is Haemophilia A (1 mark)"},{"id":"b","label":"Part B","prompt":"How is the severity of Haemophilia defined into mild, moderate and severe (3 marks)"},{"id":"c","label":"Part C","prompt":"What is the likely diagnosis in this case? (1 mark)"},{"id":"d","label":"Part D","prompt":"Outline two aspects of supportive care in this case (2 marks)"},{"id":"e","label":"Part E","prompt":"State the specific factor replacement, including initial dose and target (3 marks)"},{"id":"f","label":"Part F","prompt":"How would this dose be altered in the setting of intracranial haemorrhage, and why? (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Deficiency of Factor 8</span></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Based on amount of residual active factor 8</span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Mild = 5-40% active factor</span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Moderate = 1-5% active factor</span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Severe = &lt;1% active factor</span></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Haemathrosis (most common presentation of Haemophilia A)</span></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><span class=\"answer-source-red\">1.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Analgesia: oral paracetamol 450mg, oxycodone 2.5mg </span></div><div class=\"answer-line\"><span class=\"answer-source-red\">2.</span><span class=\"answer-source-red\"> </span><span class=\"answer-source-red\">Splinting/immobilisation</span></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Recombinant factor 8</span></div><div class=\"answer-line\"><span class=\"answer-source-red\">1unit /kg raises activity by 2%</span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Target 50% activity in haemarthrosis</span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Thus 25u/kg = 25x30 = 750 units</span></div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\"><span class=\"answer-source-red\">Target 100% activity in life-threatening bleeding</span></div><div class=\"answer-line\"><span class=\"answer-source-red\">Thus 50u/kg = 1,500 units</span></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 13 year old boy presents after a head collision whilst playing rugby. He had a witnessed loss of consciousness lasting approximately 10 seconds and was assisted from the field. He has been transported to your ED by his parents. He is GCS 15 and you are not concerned about an intracranial bleed. Your diagnosis is concussion. You are planning to discharge the patient from your department Aside from headache, list 5 symptoms of concussion that may occur in the days following the injury (5 marks) Name one assessment tool, which may assist in the diagnosis and ongoing monitoring for a patient with a concussion (1 mark)","parts":[{"id":"a","label":"Part A","prompt":"The boy tells you his Grand Final match is in 1 week. Outline your discharge advice (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><span class=\"answer-source-red\"><strong>Rest</strong></span><span class=\"answer-source-red\"> (body and mind) </span></td></tr><tr><td><span class=\"answer-source-red\">-</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Time course of recovery and symptoms (is variable) </span></td></tr><tr><td><span class=\"answer-source-red\">-</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\"><strong>Graded return to play plan</strong></span><span class=\"answer-source-red\">(in some capacity – ideally state a graded return to play guided </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">by a medical professional). 3 weeks is the minimal plausible time to return, however  further </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">caution often taken in paediatric patients  </span></td></tr><tr><td><span class=\"answer-source-red\">-</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Return to school, or a statement about emotional/concentration/learning difficulty post </span></td></tr><tr><td colspan=\"2\"><span class=\"answer-source-red\">concussion) </span></td></tr><tr><td><span class=\"answer-source-red\">-</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\"><strong>Adequate follow up</strong></span><span class=\"answer-source-red\"> (GP, paed, sports med) </span></td></tr><tr><td><span class=\"answer-source-red\">-</span><span class=\"answer-source-red\"> </span></td><td><span class=\"answer-source-red\">Others accepted </span></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 45 year old man presents with shoulder pain. A junior doctor has performed an X ray which shows no fracture. She plans to discharge him with a diagnosis of ‘soft tissue injury’.","parts":[{"id":"a","label":"Part A","prompt":"Complete the following table (12 marks) Time course Mechanism Specific physical (Acute, sub- examination test acute, chronic) Subacromial impingement Glenoid labrum tear AC joint sprain Adhesive Capsulitis"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"4\">A 45 year old man presents with shoulder pain. A junior doctor has performed an X ray which shows</td></tr><tr><td colspan=\"4\">no fracture. She plans to discharge him with a diagnosis of ‘soft tissue injury’.</td></tr><tr><td>Time course</td><td>Mechanism</td><td>Specific physical examination</td><td></td></tr><tr><td>(Acute, sub-acute,</td><td>test</td><td></td><td></td></tr><tr><td colspan=\"4\">chronic)</td></tr><tr><td>Subacromial</td><td><span class=\"answer-source-red\">Sub-Acute or chronic </span></td><td><span class=\"answer-source-red\">Rotator cuff weakness/tear </span></td><td><span class=\"answer-source-red\">Neer </span></td></tr><tr><td>impingement</td><td><span class=\"answer-source-red\">with superior migration of </span></td><td><span class=\"answer-source-red\">Hawkins-Kennedy </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">humerus </span></td><td><span class=\"answer-source-red\">Painful Arc </span></td><td></td><td></td></tr><tr><td colspan=\"4\"><span class=\"answer-source-red\">Jobe test </span></td></tr><tr><td>Glenoid labrum</td><td><span class=\"answer-source-red\">Acute </span></td><td><span class=\"answer-source-red\">Overhead throwing </span></td><td><span class=\"answer-source-red\">Active compression test </span></td></tr><tr><td>tear</td><td><span class=\"answer-source-red\">Fall on outstretched hand </span></td><td><span class=\"answer-source-red\">(O’Briens) </span></td><td></td></tr><tr><td><span class=\"answer-source-red\">with tensed biceps </span></td><td><span class=\"answer-source-red\">Crank test </span></td><td></td><td></td></tr><tr><td>AC joint sprain</td><td><span class=\"answer-source-red\">Acute </span></td><td><span class=\"answer-source-red\">Direct blow to shoulder or </span></td><td><span class=\"answer-source-red\">Cross body adduction </span></td></tr><tr><td><span class=\"answer-source-red\">fall onto shoulder tip </span></td><td><span class=\"answer-source-red\">Will accept noticeable step </span></td><td></td><td></td></tr><tr><td colspan=\"4\"><span class=\"answer-source-red\">deformity/asymmetry </span></td></tr><tr><td>Adhesive</td><td><span class=\"answer-source-red\">Sub acute or chronic </span></td><td><span class=\"answer-source-red\">Idiopathic (will accept as </span></td><td><span class=\"answer-source-red\">Symmetric loss of active and </span></td></tr><tr><td>Capsulitis</td><td><span class=\"answer-source-red\">this is most common) </span></td><td><span class=\"answer-source-red\">passive ROM </span></td><td></td></tr><tr><td colspan=\"4\"><span class=\"answer-source-red\">Post trauma, or post </span></td></tr><tr><td colspan=\"4\"><span class=\"answer-source-red\">surgical </span></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
